<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>2048 Game</title>
    <style>
        body {
            font-family: sans-serif;
            background-color: #bbada0;
            color: #776e65;
            text-align: center;
            margin: 0;
            padding: 20px;
        }

        h1 {
            font-size: 48px;
            margin-bottom: 10px;
        }

        .header-container {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 20px;
        }

        #score {
            background-color: #bbada0;
            border-radius: 6px;
            color: white;
            font-weight: bold;
            padding: 10px 20px;
            min-width: 80px;
            text-align: center;
        }

        .controls {
            margin-bottom: 20px;
        }

        #board {
            display: grid;
            grid-template-columns: repeat(4, 100px);
            grid-template-rows: repeat(4, 100px);
            gap: 10px;
            background-color: #bbada0;
            border-radius: 6px;
            padding: 10px;
            margin: 0 auto;
        }

        .tile {
            width: 100px;
            height: 100px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 36px;
            font-weight: bold;
            border-radius: 4px;
            color: #776e65;
        }

        .tile-0 {
            background-color: #cdc1b4;
        }

        .tile-2 {
            background-color: #eee4da;
        }

        .tile-4 {
            background-color: #ede0c8;
        }

        .tile-8 {
            background-color: #f2b179;
            color: white;
        }

        .tile-16 {
            background-color: #f59563;
            color: white;
        }

        .tile-32 {
            background-color: #f67c5f;
            color: white;
        }

        .tile-64 {
            background-color: #f65e3b;
            color: white;
        }

        .tile-128 {
            background-color: #edcf72;
            color: white;
            font-size: 30px;
        }

        .tile-256 {
            background-color: #edcc61;
            color: white;
            font-size: 30px;
        }

        .tile-512 {
            background-color: #edc850;
            color: white;
            font-size: 30px;
        }

        .tile-1024 {
            background-color: #edc53f;
            color: white;
            font-size: 24px;
        }

        .tile-2048 {
            background-color: #edc22e;
            color: white;
            font-size: 24px;
        }

        .tile-super {
            background-color: #3c3a32;
            color: white;
            font-size: 18px;
        }

        button#reset {
            background-color: #8f7a66;
            border-radius: 6px;
            color: white;
            padding: 10px 20px;
            font-weight: bold;
            cursor: pointer;
            border: none;
            font-size: 16px;
        }

        button#reset:hover {
            background-color: #7f6a56;
        }
    </style>
</head>
<body>
    <h1>2048</h1>

    <div class="header-container">
        <div id="score">0</div>
        <button id="reset">New Game</button>
    </div>

    <div id="board"></div>

    <script>
        // Game state
        let boardData = [];
        let scoreValue = 0;
        const size = 4;

        function init() {
            createBoardUI();
            window.game.reset();

            // Add event listener for arrow keys
            document.addEventListener('keydown', (e) => {
                if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
                    e.preventDefault();

                    let direction;
                    switch(e.key) {
                        case 'ArrowUp': direction = 'up'; break;
                        case 'ArrowDown': direction = 'down'; break;
                        case 'ArrowLeft': direction = 'left'; break;
                        case 'ArrowRight': direction = 'right'; break;
                    }

                    if (window.game.move(direction)) {
                        // Update the UI after move
                        renderBoard();
                    }
                }
            });

            document.getElementById('reset').addEventListener('click', () => {
                window.game.reset();
            });
        }

        function createBoardUI() {
            const boardElement = document.getElementById('board');
            boardElement.innerHTML = '';
            for (let i = 0; i < size * size; i++) {
                const tile = document.createElement('div');
                tile.id = `tile-${i}`;
                tile.className = 'tile tile-0';
                boardElement.appendChild(tile);
            }
        }

        function renderBoard() {
            const currentBoard = window.game.board();
            const scoreDisplay = document.getElementById('score');

            // Update score
            scoreDisplay.textContent = window.game.score();

            // Update tiles
            for (let i = 0; i < size * size; i++) {
                const tileValue = currentBoard[Math.floor(i / size)][i % size];
                const tileElement = document.getElementById(`tile-${i}`);

                // Remove all class names starting with 'tile-'
                tileElement.className = 'tile';

                // Add new class based on value
                if (tileValue > 0) {
                    tileElement.textContent = tileValue;
                    tileElement.classList.add(tileValue <= 2048 ? `tile-${tileValue}` : 'tile-super');
                } else {
                    tileElement.textContent = '';
                    tileElement.classList.add('tile-0');
                }
            }
        }

        // Slide and merge a single row (left direction)
        function slideRow(row) {
            // Remove zeros
            let filtered = row.filter(num => num !== 0);

            // Merge adjacent equal numbers
            for (let i = 0; i < filtered.length - 1; i++) {
                if (filtered[i] === filtered[i + 1]) {
                    filtered[i] *= 2;
                    scoreValue += filtered[i];
                    filtered[i + 1] = 0;
                    // Skip next element since it's been merged
                    i++;
                }
            }

            // Remove zeros again (from merges)
            filtered = filtered.filter(num => num !== 0);

            // Pad with zeros to reach row length
            while (filtered.length < size) {
                filtered.push(0);
            }

            return filtered;
        }

        window.game = {
            size: size,

            reset: function() {
                boardData = Array(size).fill().map(() => Array(size).fill(0));
                scoreValue = 0;

                // Add two random tiles
                let emptyCells = [];
                for (let r = 0; r < size; r++) {
                    for (let c = 0; c < size; c++) {
                        if (boardData[r][c] === 0) {
                            emptyCells.push({r, c});
                        }
                    }
                }

                // Add first random tile
                if (emptyCells.length > 0) {
                    const idx1 = Math.floor(Math.random() * emptyCells.length);
                    const cell1 = emptyCells[idx1];
                    boardData[cell1.r][cell1.c] = Math.random() < 0.9 ? 2 : 4;
                    emptyCells.splice(idx1, 1);
                }

                // Add second random tile
                if (emptyCells.length > 0) {
                    const idx2 = Math.floor(Math.random() * emptyCells.length);
                    const cell2 = emptyCells[idx2];
                    boardData[cell2.r][cell2.c] = Math.random() < 0.9 ? 2 : 4;
                }

                renderBoard();
            },

            move: function(direction) {
                let changed = false;
                let newBoard = Array(size).fill().map(() => Array(size).fill(0));
                let oldScore = scoreValue;

                // Copy current board to newBoard
                for (let r = 0; r < size; r++) {
                    for (let c = 0; c < size; c++) {
                        newBoard[r][c] = boardData[r][c];
                    }
                }

                if (direction === 'left') {
                    // Slide each row left
                    for (let r = 0; r < size; r++) {
                        let row = boardData[r].slice();
                        let newRow = slideRow(row);

                        for (let c = 0; c < size; c++) {
                            if (boardData[r][c] !== newRow[c]) {
                                changed = true;
                            }
                            newBoard[r][c] = newRow[c];
                        }
                    }
                } else if (direction === 'right') {
                    // Slide each row right (reverse, slide left, reverse)
                    for (let r = 0; r < size; r++) {
                        let row = boardData[r].slice().reverse();
                        let newRow = slideRow(row).reverse();

                        for (let c = 0; c < size; c++) {
                            if (boardData[r][c] !== newRow[c]) {
                                changed = true;
                            }
                            newBoard[r][c] = newRow[c];
                        }
                    }
                } else if (direction === 'up') {
                    // Slide each column up
                    for (let c = 0; c < size; c++) {
                        let col = [];
                        for (let r = 0; r < size; r++) {
                            col.push(boardData[r][c]);
                        }

                        let newCol = slideRow(col);

                        for (let r = 0; r < size; r++) {
                            if (boardData[r][c] !== newCol[r]) {
                                changed = true;
                            }
                            newBoard[r][c] = newCol[r];
                        }
                    }
                } else if (direction === 'down') {
                    // Slide each column down (reverse, slide left, reverse)
                    for (let c = 0; c < size; c++) {
                        let col = [];
                        for (let r = 0; r < size; r++) {
                            col.push(boardData[r][c]);
                        }

                        let newCol = slideRow(col.reverse()).reverse();

                        for (let r = 0; r < size; r++) {
                            if (boardData[r][c] !== newCol[r]) {
                                changed = true;
                            }
                            newBoard[r][c] = newCol[r];
                        }
                    }
                }

                // If board changed, update and spawn new tile
                if (changed) {
                    boardData = newBoard;

                    // Add new tile to random empty cell
                    let emptyCells = [];
                    for (let r = 0; r < size; r++) {
                        for (let c = 0; c < size; c++) {
                            if (boardData[r][c] === 0) {
                                emptyCells.push({r, c});
                            }
                        }
                    }

                    if (emptyCells.length > 0) {
                        const idx = Math.floor(Math.random() * emptyCells.length);
                        const cell = emptyCells[idx];
                        boardData[cell.r][cell.c] = Math.random() < 0.9 ? 2 : 4;
                    }
                }

                // Update the UI
                renderBoard();

                return changed;
            },

            board: function() {
                return boardData.map(row => row.slice());
            },

            setBoard: function(arr) {
                boardData = arr.map(row => row.slice());
                scoreValue = 0; // Reset score when manually setting board
            },

            score: function() {
                return scoreValue;
            }
        };

        // Initialize the game
        init();
    </script>
</body>
</html>
